<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\AboutSetting; use Illuminate\Http\Request;
class AboutSettingController extends Controller { public function edit(){return view('admin.about-settings.edit',['aboutSetting'=>AboutSetting::current()]);} public function update(Request $r){$d=$r->validate(['story_heading'=>'nullable|string|max:255','story_body'=>'nullable|string|max:10000','vision_heading'=>'required|string|max:255','vision_body'=>'nullable|string|max:10000','mission_heading'=>'required|string|max:255','mission_body'=>'nullable|string|max:10000','motto'=>'nullable|string|max:255','motto_explanation'=>'nullable|string|max:5000']);AboutSetting::current()->update($d);return back()->with('success','About section updated.');} }
